impl Request {
    pub(crate) fn parse(line: &[u8]) -> Result<Self, Error> {
        let value: Value = serde_json::from_slice(line).map_err(|e| {
            Error::new(ErrorCode::InvalidRequest, format!("the line is not valid JSON: {e}"))
        })?;
