                }
            }
        }
        steps
    }

    fn deliver(
        &mut self,
        sequence: SequenceNumber,
        until: Duration,
        now: Duration,
        ids: &mut Ids,
    ) -> ReceivedMessage {
        let message = self
            .messages
            .get_mut(&sequence)
            .expect("planned sequence numbers are in the queue");
