        queue.in_flight(receipt, self.now).ok_or_else(|| {
            Error::new(
                ErrorCode::ReceiptHandleExpired,
                format!("receipt handle {receipt_handle:?} no longer refers to a message in flight in this queue"),
            )
        })
    }

