        fifo_send("b", "g2", "d"),       // duplicate, original ids come back
        tick(1),                          // 300 after the first send
        fifo_send("c", "g1", "d"),       // accepted, opens a new window
        fifo_send("e", "g1", "other"),
    ]);
    assert_eq!(responses[1], json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
    assert_eq!(responses[3], responses[1]);
    assert_eq!(responses[5], json!({"ok": true, "MessageId": "m-2", "SequenceNumber": 2}));
    assert_eq!(responses[6], json!({"ok": true, "MessageId": "m-3", "SequenceNumber": 3}));
}

